python3 -c "
import PIL, numpy; print('PIL', PIL.__version__); print('numpy', numpy.__version__)
try:
  import scipy; print('scipy', scipy.__version__)
except Exception as e: print('no scipy', e)
from PIL import features; print('webp', features.check('webp'), 'webp_anim', features.check('webp_anim'))
"
echo "--- browsers ---"
for b in chromium chromium-browser google-chrome google-chrome-stable firefox node npx; do printf "%s: %s\n" "$b" "$(which $b 2>/dev/null || echo -)"; done
python3 -c "import playwright; print('playwright ok')" 2>&1 | tail -1
